    l_scr_tab_kds: "Экран кухни", l_scr_tab_tg: "Telegram-бот", l_scr_caption: "* Демонстрация — иллюстрация на основе реальной структуры модуля",
    l_int_eyebrow: "Интеграции", l_int_title: "Готовые интеграции с местными сервисами", l_int_lede: "Сервисы, необходимые для рынка Узбекистана, уже подключены.",
    l_int1_d: "База данных в реальном времени", l_int2_d: "Отчёты и оповещения", l_int3_d: "Система онлайн-платежей", l_int4_d: "Система онлайн-платежей", l_int5_d: "Система онлайн-платежей",
    l_int6_d: "Адрес и маршрут", l_int7_d: "Внешняя курьерская служба — скоро", l_int8_t: "Принтеры", l_int8_d: "Чековые и кухонные принтеры",
