    // ══════════════ DOCUMENTATION (guid.html) ══════════════
    doc_page_title: "Nesta ERP — User Manual",
    doc_search_placeholder: "Search the manual...",
    doc_search_noresults: "No results found",
    doc_back_to_login: "Back to login",
    doc_dark_mode: "Dark mode",
    doc_nav_intro: "Introduction",
